<?php

namespace Timeless\Blocks;

use function esc_attr;
use function esc_html;
use function esc_url;
use function get_block_wrapper_attributes;
use function sanitize_html_class;
use function sprintf;
use function wp_kses_post;

class SocialSharingIconBlock extends AbstractBlock
{
    protected string $blockId = 'jankx/social-sharing-icon';

    protected function renderBlock(array $attributes, string $content, ?\WP_Block $block): string
    {
        $network = $attributes['network'] ?? '';
        $iconSize = $attributes['iconSize'] ?? 'medium';
        $showLabel = $attributes['showLabel'] ?? true;
        $customIcon = $attributes['customIcon'] ?? '';
        $customLabel = $attributes['customLabel'] ?? '';
        $url = $attributes['url'] ?? '';
        $title = $attributes['title'] ?? '';

        if ($network === '' && $customIcon === '' && $url === '') {
            return '';
        }

        $classes = array_filter([
            'jankx-social-sharing-icon',
            'social-sharing-icon--size-' . sanitize_html_class($iconSize),
            $network !== '' ? 'network-' . sanitize_html_class($network) : '',
        ]);

        $wrapperAttributes = get_block_wrapper_attributes([
            'class' => implode(' ', $classes),
        ]);

        $label = $customLabel !== '' ? $customLabel : ($network !== '' ? ucfirst($network) : '');
        $icon = $customIcon !== '' ? $customIcon : $this->getNetworkIcon($network);

        $shareUrl = $url !== '' ? $url : $this->getNetworkShareUrl($network, $title);

        if ($shareUrl === '') {
            return sprintf(
                '<span %s>%s</span>',
                $wrapperAttributes,
                esc_html($label)
            );
        }

        $targetAttr = $network === 'email' ? '' : ' target="_blank"';
        $relAttr = $network === 'email' ? '' : ' rel="noopener noreferrer"';

        return sprintf(
            '<a %s href="%s"%s%s class="social-sharing-link" aria-label="%s">%s%s</a>',
            $wrapperAttributes,
            esc_url($shareUrl),
            $targetAttr,
            $relAttr,
            esc_attr($label),
            $icon,
            $showLabel && $label !== '' ? '<span class="social-sharing-icon-label">' . esc_html($label) . '</span>' : ''
        );
    }

    protected function shouldRender(array $attributes): bool
    {
        return true;
    }

