    private function getNetworkShareUrl(string $network, string $title): string
    {
        $url = get_permalink();
        $text = urlencode($title);

        switch ($network) {
            case 'facebook':
                return 'https://www.facebook.com/sharer/sharer.php?u=' . urlencode($url);
            case 'twitter':
                return 'https://twitter.com/intent/tweet?text=' . $text . '&url=' . urlencode($url);
            case 'linkedin':
                return 'https://www.linkedin.com/sharing/share-offsite/?url=' . urlencode($url);
            case 'pinterest':
                return 'https://pinterest.com/pin/create/button/?url=' . urlencode($url) . '&description=' . $text;
            case 'telegram':
                return 'https://t.me/share/url?url=' . urlencode($url) . '&text=' . $text;
            case 'whatsapp':
                return 'https://wa.me/?text=' . $text . '%20' . urlencode($url);
            case 'email':
                return 'mailto:?subject=' . $text . '&body=' . urlencode($url);
            case 'copy':
                return '#';
            default:
                return '';
        }
    }
}
